import { useEffect, useState } from "react";
import { useParams } from "react-router-dom";
import axios from "axios";
import { Card, CardContent, Typography, List, ListItem, ListItemText } from "@mui/material";

const CandidateParrainages = () => {
    const { id } = useParams(); // Récupérer l'ID du candidat depuis l'URL
    const [parrainages, setParrainages] = useState([]);

    useEffect(() => {
        axios.get(`http://localhost:5000/api/candidats/${id}/parrainages`)
            .then(response => setParrainages(response.data))
            .catch(error => console.error("Erreur lors du chargement des parrainages:", error));
    }, [id]);

    return (
        <Card>
            <CardContent>
                <Typography variant="h5">Parrainages reçus</Typography>
                {parrainages.length > 0 ? (
                    <List>
                        {parrainages.map((electeur, index) => (
                            <ListItem key={index}>
                                <ListItemText primary={`${electeur.nom} ${electeur.prenom}`}
                                              secondary={`Carte électeur: ${electeur.numCarteElecteur} | Né(e) le: ${electeur.date_naissance}`} />
                            </ListItem>
                        ))}
                    </List>
                ) : (
                    <Typography>Aucun parrainage reçu.</Typography>
                )}
            </CardContent>
        </Card>
    );
};

export default CandidateParrainages;
